import React, { useState, useEffect } from 'react';
import { Flow } from 'flow-sdk';
import { 
  SectionLabel, 
  PillButton, 
  FieldDropdown, 
  TextInput, 
  SegmentedToggle, 
  DragNumberField 
} from './components/UI';
import { SYSTEM_PROMPT_HEAD, SYSTEM_PROMPT_TAIL } from './constants';

export default function App() {
  const [scene, setScene] = useState('');
  const [tags, setTags] = useState('');
  const [accentColor, setAccentColor] = useState<'Orange' | 'Blue' | 'Red'>('Orange');
  const [paletteMode, setPaletteMode] = useState<'Light' | 'Dark'>('Light');
  const [isProfessional, setIsProfessional] = useState(false);
  const [isAncient, setIsAncient] = useState(false);
  const [isLoading, setIsLoading] = useState(false);
  const [result, setResult] = useState<{ base64: string; mimeType: string; mediaId: string } | null>(null);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    const id = 'flow-design-system-css';
    if (document.getElementById(id)) return;
    const style = document.createElement('style');
    style.id = id;
    style.textContent = `
      html, body, #root { margin: 0; padding: 0; width: 100%; height: 100%; background: #0e0e0e; font-family: 'Google Sans Text', sans-serif; color: white; overflow: hidden; }
      .shimmer { background: linear-gradient(90deg, #1a1a1a 25%, #2a2a2a 50%, #1a1a1a 75%); background-size: 200% 100%; animation: shimmer 1.5s infinite; }
      @keyframes shimmer { 0% { background-position: 200% 0; } 100% { background-position: -200% 0; } }
      @keyframes fade-in { from { opacity: 0; transform: translateY(10px); } to { opacity: 1; transform: translateY(0); } }
      .animate-fade-in { animation: fade-in 0.4s ease-out forwards; }
    `;
    document.head.appendChild(style);
  }, []);

  const handleGenerate = async () => {
    if (!scene.trim()) {
      setError("Please describe a scene first.");
      return;
    }

    setIsLoading(true);
    setError(null);

    // Construct the final prompt based on the System Prompt requirements
    const modeTrigger = paletteMode === 'Dark' ? '[Dark Mode / Oppressive Atmosphere]' : '[Light Mode / Airy Atmosphere]';
    const professionTrigger = isProfessional ? '[Profession Mode Activated]' : '[Default Clothing Mode]';
    const eraTrigger = isAncient ? '[Ancient/Prehistoric Mode Activated - FORCE ORANGE]' : '';
    const tagBlock = tags ? `[${tags}]` : '';

    const fullPrompt = `
      ${SYSTEM_PROMPT_HEAD}

      CURRENT SELECTION OVERRIDES:
      - Palette: ${paletteMode}
      - Forced Accent Logic: ${isAncient ? 'Orange' : accentColor}
      - Mode: ${isProfessional ? 'Professional' : 'Default'}

      ${tagBlock} ${modeTrigger} ${professionTrigger} ${eraTrigger}

      SCENE DESCRIPTION:
      ${scene}

      ${SYSTEM_PROMPT_TAIL}
    `;

    try {
      const img = await Flow.generate.image({
        prompt: fullPrompt,
        modelDisplayName: "🍌 Nano Banana Pro",
        aspectRatio: '16:9'
      });
      setResult(img);
    } catch (err: any) {
      setError(err.message || "Failed to generate illustration.");
    } finally {
      setIsLoading(false);
    }
  };

  const handleDownload = async () => {
    if (!result) return;
    await Flow.download({
      base64: result.base64,
      mimeType: result.mimeType,
      filename: `B2_Illustration_${Date.now()}.png`
    });
  };

  return (
    <div className="flex h-full w-full bg-[#0e0e0e]">
      {/* Left Settings Panel */}
      <div className="relative border-r border-[rgba(218,220,224,0.15)] flex flex-col items-start justify-between overflow-y-auto overflow-x-hidden px-[10px] py-[12px] w-[320px] h-full shrink-0">
        <div className="flex flex-col gap-[24px] items-start w-full">

          <div className="flex flex-col gap-2 items-start w-full">
            <SectionLabel>Scene Input</SectionLabel>
            <div className="flex flex-col gap-1.5 w-full">
              <TextInput 
                value={tags} 
                onChange={setTags} 
                placeholder="[Tags] e.g. tropical, office, night" 
              />
              <textarea 
                value={scene} 
                onChange={(e) => setScene(e.target.value)} 
                placeholder="Describe the action..."
                className="border border-[#595959] hover:border-[#7a7a7a] focus:border-[#969696] rounded-xl w-full h-[120px] px-3 py-2.5 resize-none bg-transparent text-[12px] font-medium text-white placeholder-[rgba(218,220,224,0.4)] tracking-[0.1px] focus:outline-none transition-colors"
              />
            </div>
          </div>

          <div className="flex flex-col gap-2 items-start w-full">
            <SectionLabel>Style Configuration</SectionLabel>
            <div className="flex flex-col gap-2 w-full">
              <SegmentedToggle 
                value={paletteMode}
                onChange={(v) => setPaletteMode(v as any)}
                items={[
                  { value: 'Light', label: 'Light Mode' },
                  { value: 'Dark', label: 'Dark Mode' }
                ]}
              />
              <div className="flex gap-1 w-full">
                <FieldDropdown 
                  label="Accent Color" 
                  value={isAncient ? 'Orange (Forced)' : accentColor} 
                  options={['Orange', 'Blue', 'Red']} 
                  onChange={(v) => setAccentColor(v as any)}
                  className="flex-1"
                />
              </div>
            </div>
          </div>

          <div className="flex flex-col gap-2 items-start w-full">
            <SectionLabel>Character Mode</SectionLabel>
            <div className="flex flex-col gap-1.5 w-full">
              <div className="flex gap-1 w-full">
                <PillButton 
                  variant={isProfessional ? 'filled' : 'outline'}
                  onClick={() => setIsProfessional(!isProfessional)}
                  icon={<span className="material-symbols-outlined text-[18px]">work</span>}
                >
                  Profession
                </PillButton>
                <PillButton 
                  variant={isAncient ? 'filled' : 'outline'}
                  onClick={() => setIsAncient(!isAncient)}
                  icon={<span className="material-symbols-outlined text-[18px]">history_edu</span>}
                >
                  Ancient
                </PillButton>
              </div>
            </div>
          </div>

        </div>

        <div className="flex flex-col gap-2 w-full pt-4 border-t border-[rgba(218,220,224,0.1)]">
          {error && <p className="text-red-400 text-[10px] px-2">{error}</p>}
          <PillButton 
            variant="solid" 
            onClick={handleGenerate} 
            disabled={isLoading}
            icon={isLoading ? undefined : <span className="material-symbols-outlined text-[18px]">auto_awesome</span>}
          >
            {isLoading ? 'Illustrating...' : 'Generate B-2'}
          </PillButton>
        </div>
      </div>

      {/* Main Preview Area */}
      <div className="flex-1 h-full flex flex-col items-center justify-center p-8 bg-[#0a0a0a] overflow-hidden relative">
        <div className="w-full max-w-[1200px] aspect-video relative group">
          {isLoading ? (
            <div className="absolute inset-0 rounded-2xl shimmer flex flex-col items-center justify-center gap-4 border border-white/10 shadow-2xl">
              <div className="flex items-center gap-3 bg-black/40 px-6 py-3 rounded-full backdrop-blur-md border border-white/10">
                <div className="w-4 h-4 border-2 border-white/30 border-t-white rounded-full animate-spin" />
                <span className="text-sm font-medium tracking-widest uppercase opacity-80">Assembling Illustration...</span>
              </div>
            </div>
          ) : result ? (
            <div className="relative w-full h-full animate-fade-in">
              <img 
                src={`data:${result.mimeType};base64,${result.base64}`} 
                className="w-full h-full object-cover rounded-2xl border border-white/10 shadow-2xl"
                alt="B-2 Illustration"
              />
              <div className="absolute bottom-4 right-4 opacity-0 group-hover:opacity-100 transition-opacity flex gap-2">
                <PillButton 
                  variant="solid" 
                  onClick={handleDownload}
                  icon={<span className="material-symbols-outlined text-[18px]">download</span>}
                >
                  Download PNG
                </PillButton>
              </div>
            </div>
          ) : (
            <div className="absolute inset-0 rounded-2xl border-2 border-dashed border-white/10 flex flex-col items-center justify-center text-white/20 gap-4">
              <span className="material-symbols-outlined text-6xl">brush</span>
              <p className="text-sm font-medium tracking-widest uppercase">Input scene to begin illustration</p>
            </div>
          )}
        </div>

        {/* Status Bar */}
        {result && !isLoading && (
          <div className="mt-6 px-4 py-2 rounded-full bg-white/5 border border-white/10 flex items-center gap-4 text-[11px] text-white/50 uppercase tracking-widest">
            <div className="flex items-center gap-1.5">
              <span className="w-2 h-2 rounded-full bg-green-500 shadow-[0_0_8px_rgba(34,197,94,0.6)]" />
              <span>Style Locked: B-2 Digital Editorial</span>
            </div>
            <div className="w-px h-3 bg-white/10" />
            <span>Resolution: 1920x1080</span>
            <div className="w-px h-3 bg-white/10" />
            <span>Model: Nano Banana Pro</span>
          </div>
        )}
      </div>
    </div>
  );
}

import React, { useState, useRef, useEffect } from 'react';

export const SectionLabel: React.FC<{ children: React.ReactNode }> = ({ children }) => (
  <div className="flex items-center px-2">
    <span className="text-[11px] font-medium text-[rgba(218,220,224,0.9)] tracking-[0.1px] uppercase">
      {children}
    </span>
  </div>
);

export const PillButton: React.FC<{
  icon?: React.ReactNode; 
  children: React.ReactNode;
  variant?: 'filled' | 'outline' | 'solid'; 
  onClick?: () => void;
  disabled?: boolean;
}> = ({ icon, children, variant = 'filled', onClick, disabled }) => {
  const base = 'flex items-center gap-[6px] justify-center w-full h-[36px] rounded-xl font-medium tracking-[0.1px] transition-all cursor-pointer disabled:opacity-30 disabled:cursor-not-allowed';
  const variants: Record<string, string> = {
    filled: 'bg-[#969696] hover:bg-[#a6a6a6] active:bg-[#868686] text-black text-[11px] px-3',
    outline: 'border border-[#595959] hover:bg-white/5 active:bg-white/10 text-[11px] px-3 text-white',
    solid: 'bg-white hover:bg-gray-200 active:bg-gray-300 text-black text-[11px] px-3',
  };
  return (
    <button className={`${base} ${variants[variant]}`} onClick={onClick} disabled={disabled}>
      {icon && <span className="flex items-center justify-center">{icon}</span>}
      <span>{children}</span>
    </button>
  );
};

export const FieldDropdown: React.FC<{
  label: string; 
  value: string; 
  options: string[];
  onChange: (val: string) => void; 
  className?: string;
}> = ({ label, value, options, onChange, className = '' }) => {
  const [isOpen, setIsOpen] = useState(false);
  const ref = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const listener = (e: MouseEvent) => {
      if (!ref.current || ref.current.contains(e.target as Node)) return;
      setIsOpen(false);
    };
    document.addEventListener('mousedown', listener);
    return () => document.removeEventListener('mousedown', listener);
  }, []);

  return (
    <div ref={ref} className={`relative ${className}`}>
      <button type="button" onClick={() => setIsOpen(!isOpen)}
        className="w-full text-left border border-[#595959] hover:border-[#7a7a7a] transition-colors rounded-xl flex flex-col gap-0.5 justify-center pb-2 pl-3 pr-2 pt-[6px] select-none focus:outline-none bg-transparent">
        <p className="text-[10px] font-medium text-[rgba(255,255,255,0.35)] tracking-[0.5px] uppercase">{label}</p>
        <div className="flex items-center justify-between">
          <span className="text-[11px] font-medium text-white tracking-[0.1px]">{value}</span>
          <span className={`material-symbols-outlined text-[16px] text-[rgba(218,220,224,0.5)] transition-transform ${isOpen ? 'rotate-180' : ''}`}>expand_more</span>
        </div>
      </button>
      {isOpen && (
        <div className="absolute z-50 top-[calc(100%+4px)] left-0 w-full bg-[#1a1a1a] border border-[#595959] rounded-xl overflow-hidden shadow-2xl backdrop-blur-md animate-dropdown origin-top">
          <div className="max-h-40 overflow-y-auto dark-scrollbar">
            {options.map((opt) => (
              <button key={opt} type="button"
                className={`w-full text-left px-3 py-2 text-[11px] font-medium tracking-[0.1px] hover:bg-white/10 transition-colors ${value === opt ? 'bg-white/5 text-white' : 'text-[rgba(218,220,224,0.7)]'}`}
                onClick={() => { onChange(opt); setIsOpen(false); }}>
                {opt}
              </button>
            ))}
          </div>
        </div>
      )}
    </div>
  );
};

export const TextInput: React.FC<{
  value: string; onChange: (val: string) => void; placeholder?: string;
}> = ({ value, onChange, placeholder }) => (
  <input 
    type="text"
    value={value} 
    onChange={(e) => onChange(e.target.value)} 
    placeholder={placeholder}
    className="border border-[#595959] hover:border-[#7a7a7a] focus:border-[#969696] rounded-xl w-full h-[42px] px-3 bg-transparent text-[12px] font-medium text-white placeholder-[rgba(218,220,224,0.4)] tracking-[0.1px] focus:outline-none transition-colors" 
  />
);

export const SegmentedToggle: React.FC<{
  value: string; 
  items: { value: string; label: string; icon?: React.ReactNode }[];
  onChange: (val: string) => void;
}> = ({ value, items, onChange }) => (
  <div className="flex w-full items-center border border-[#595959] rounded-xl overflow-hidden bg-transparent p-[1px]">
    {items.map((item) => (
      <button key={item.value} type="button" onClick={() => onChange(item.value)}
        className={`flex-1 flex items-center justify-center gap-1.5 h-[32px] px-2 rounded-[10px] text-[10px] font-medium tracking-[0.5px] uppercase transition-all cursor-pointer ${
          value === item.value ? 'bg-[#969696] text-black shadow-inner' : 'text-[rgba(218,220,224,0.6)] hover:text-white hover:bg-white/5'
        }`}>
        {item.icon}<span>{item.label}</span>
      </button>
    ))}
  </div>
);

export const DragNumberField: React.FC<{
  label: string; value: number; min?: number; max?: number;
  step?: number; suffix?: string; onChange: (val: number) => void; className?: string;
}> = ({ label, value, min = 0, max = 999, step = 1, suffix = 'px', onChange, className = '' }) => {
  const [isEditing, setIsEditing] = useState(false);
  const [editValue, setEditValue] = useState(String(value));
  const inputRef = useRef<HTMLInputElement>(null);
  const dragRef = useRef<{ startY: number; startVal: number; moved: boolean } | null>(null);

  const commitEdit = (raw: string) => {
    const parsed = parseFloat(raw);
    if (!isNaN(parsed)) onChange(Math.min(max, Math.max(min, Math.round(parsed / step) * step)));
    setIsEditing(false);
  };

  const handleMouseDown = (e: React.MouseEvent) => {
    if (isEditing) return;
    e.preventDefault();
    dragRef.current = { startY: e.clientY, startVal: value, moved: false };
    const handleMouseMove = (ev: MouseEvent) => {
      if (!dragRef.current) return;
      if (Math.abs(ev.clientY - dragRef.current.startY) > 3) dragRef.current.moved = true;
      if (dragRef.current.moved) {
        const delta = dragRef.current.startY - ev.clientY;
        const newVal = Math.round((dragRef.current.startVal + delta * step) / step) * step;
        onChange(Math.min(max, Math.max(min, newVal)));
        document.body.style.cursor = 'ns-resize';
      }
    };
    const handleMouseUp = () => {
      const wasDrag = dragRef.current?.moved;
      dragRef.current = null;
      document.removeEventListener('mousemove', handleMouseMove);
      document.removeEventListener('mouseup', handleMouseUp);
      document.body.style.cursor = '';
      if (!wasDrag) {
        setEditValue(String(value));
        setIsEditing(true);
        setTimeout(() => inputRef.current?.select(), 0);
      }
    };
    document.addEventListener('mousemove', handleMouseMove);
    document.addEventListener('mouseup', handleMouseUp);
  };

  return (
    <div className={`border border-[#595959] hover:border-[#7a7a7a] rounded-xl flex flex-col gap-0.5 justify-center pb-2 pl-3 pr-2 pt-[6px] select-none transition-colors bg-transparent ${isEditing ? '' : 'cursor-ns-resize'} ${className}`}
      onMouseDown={handleMouseDown}>
      <p className="text-[10px] font-medium text-[rgba(255,255,255,0.35)] tracking-[0.5px] uppercase">{label}</p>
      <div className="flex items-center justify-between">
        {isEditing ? (
          <input ref={inputRef} type="text" value={editValue}
            onChange={(e) => setEditValue(e.target.value)}
            onKeyDown={(e) => { if (e.key === 'Enter') commitEdit(editValue); if (e.key === 'Escape') setIsEditing(false); }}
            onBlur={() => commitEdit(editValue)}
            className="bg-transparent text-[11px] font-medium text-white tracking-[0.1px] outline-none w-full border-none p-0 m-0" autoFocus />
        ) : (
          <>
            <span className="text-[11px] font-medium text-white tracking-[0.1px] cursor-text">{value}{suffix}</span>
            <div className="flex flex-col items-center opacity-30">
              <span className="material-symbols-outlined text-[12px]">unfold_more</span>
            </div>
          </>
        )}
      </div>
    </div>
  );
};
